class Verse {
  final String sadr; // الصدر (الشطر الأول)
  final String ajz; // العجز (الشطر الثاني)
  const Verse(this.sadr, this.ajz);
}

class Poem {
  final String title;
  final List<Verse> verses;
  const Poem(this.title, this.verses);
}

